     1→/**
     2→ * Conversation History Table Component
     3→ *
     4→ * Displays conversation history in a card-based format with advanced filtering
     5→ */
     6→
     7→import { useState, useEffect } from 'react';
     8→import { Spinner, Badge, Modal, Button } from 'react-bootstrap';
     9→import PropTypes from 'prop-types';
    10→import './ConversationHistoryTable.scss';
    11→
    12→const ConversationHistoryTable = ({
    13→  conversations,
    14→  loading,
    15→  phoneLines,
    16→  agents,
    17→  campaigns,
    18→  filters,
    19→  pagination,
    20→  onFilterChange,
    21→  onPageChange,
    22→  onViewDetail,
    23→  onExport,
    24→}) => {
    25→  const [localSearch, setLocalSearch] = useState(filters.search || '');
    26→  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);
    27→
    28→  // Local state for advanced filters
    29→  const [advancedFilters, setAdvancedFilters] = useState({
    30→    lineId: filters.lineId || '',
    31→    agentId: filters.agentId || '',
    32→    campaignId: filters.campaignId || '',
    33→    phoneNumber: filters.phoneNumber || '',
    34→    startDate: filters.startDate || '',
    35→    endDate: filters.endDate || '',
    36→    sortBy: filters.sortBy || 'last_message_at',
    37→    sortOrder: filters.sortOrder || 'DESC',
    38→  });
    39→
    40→  // Format date for display
    41→  const formatDate = (dateString) => {
    42→    if (!dateString) return 'N/A';
    43→    const date = new Date(dateString);
    44→    return date.toLocaleString('es-ES', {
    45→      year: 'numeric',
    46→      month: 'short',
    47→      day: 'numeric',
    48→      hour: '2-digit',
    49→      minute: '2-digit',
    50→    });
    51→  };
    52→
    53→  // Format phone number for display
    54→  const formatPhoneNumber = (phoneNumber) => {
    55→    if (!phoneNumber) return 'N/A';
    56→    // Remove non-digits and format as: +XX XXXXXXXXXX (only space after country code)
    57→    const cleaned = phoneNumber.replace(/\D/g, '');
    58→    if (cleaned.length === 12) {
    59→      return `+${cleaned.slice(0, 2)} ${cleaned.slice(2)}`;
    60→    }
    61→    return phoneNumber;
    62→  };
    63→
    64→  // Get message direction icon
    65→  const getDirectionIcon = (direction) => {
    66→    return direction === 'incoming' ? 'bi-arrow-down-left' : 'bi-arrow-up-right';
    67→  };
    68→
    69→  // Get message direction color
    70→  const getDirectionColor = (direction) => {
    71→    return direction === 'incoming' ? 'text-primary' : 'text-success';
    72→  };
    73→
    74→  // Truncate message content
    75→  const truncateMessage = (content, maxLength = 80) => {
    76→    if (!content) return 'Sin contenido';
    77→    if (content.length <= maxLength) return content;
    78→    return content.substring(0, maxLength) + '...';
    79→  };
    80→
    81→  // Get status badge variant
    82→  const getStatusBadgeVariant = (status) => {
    83→    const statusMap = {
    84→      sent: 'primary',
    85→      delivered: 'success',
    86→      read: 'info',
    87→      failed: 'danger',
    88→      received: 'secondary',
    89→      pending: 'warning',
    90→    };
    91→    return statusMap[status] || 'secondary';
    92→  };
    93→
    94→  // Get status text in Spanish
    95→  const getStatusText = (status) => {
    96→    const statusMap = {
    97→      sent: 'Enviado',
    98→      delivered: 'Entregado',
    99→      read: 'Leído',
   100→      failed: 'Fallido',
   101→      received: 'Recibido',
   102→      pending: 'Pendiente',
   103→    };
   104→    return statusMap[status] || status;
   105→  };
   106→
   107→  // Translate campaign name to Spanish
   108→  const translateCampaignName = (campaignName) => {
   109→    if (!campaignName) return campaignName;
   110→
   111→    // Common translations (handle both upper and lower case variations)
   112→    const translations = {
   113→      'schedule campaign': 'Campaña programada',
   114→      'scheduled campaign': 'Campaña programada',
   115→      'scheduled_campaign': 'Campaña programada',
   116→      'schedule_campaign': 'Campaña programada',
   117→      'schedule': 'Programada',
   118→    };
   119→
   120→    // Check for exact matches (case insensitive)
   121→    const lowerName = campaignName.toLowerCase();
   122→    for (const [key, value] of Object.entries(translations)) {
   123→      if (lowerName === key) {
   124→        return value;
   125→      }
   126→    }
   127→
   128→    // Check for partial matches and replace
   129→    let translatedName = campaignName;
   130→    for (const [key, value] of Object.entries(translations)) {
   131→      const regex = new RegExp(key, 'gi');
   132→      if (regex.test(translatedName)) {
   133→        translatedName = translatedName.replace(regex, value);
   134→      }
   135→    }
   136→
   137→    return translatedName;
   138→  };
   139→
   140→  // Handle search input with debounce
   141→  useEffect(() => {
   142→    const timer = setTimeout(() => {
   143→      onFilterChange({ search: localSearch });
   144→    }, 500);
   145→
   146→    return () => clearTimeout(timer);
   147→  }, [localSearch]);
   148→
   149→  // Apply advanced filters
   150→  const handleApplyAdvancedFilters = () => {
   151→    onFilterChange(advancedFilters);
   152→    setShowAdvancedFilters(false);
   153→  };
   154→
   155→  // Clear advanced filters
   156→  const handleClearAdvancedFilters = () => {
   157→    const clearedFilters = {
   158→      lineId: '',
   159→      agentId: '',
   160→      campaignId: '',
   161→      phoneNumber: '',
   162→      startDate: '',
   163→      endDate: '',
   164→      sortBy: 'last_message_at',
   165→      sortOrder: 'DESC',
   166→    };
   167→    setAdvancedFilters(clearedFilters);
   168→    onFilterChange(clearedFilters);
   169→    setShowAdvancedFilters(false);
   170→  };
   171→
   172→  // Count active filters
   173→  const activeFilterCount = Object.values(advancedFilters).filter(
   174→    (value) => value && value !== 'last_message_at' && value !== 'DESC'
   175→  ).length;
   176→
   177→  // Get active filter labels
   178→  const getActiveFilters = () => {
   179→    const filters = [];
   180→
   181→    if (advancedFilters.lineId) {
   182→      const line = phoneLines.find(l => l.id === parseInt(advancedFilters.lineId));
   183→      if (line) filters.push({ key: 'lineId', label: `Línea: ${line.name}` });
   184→    }
   185→
   186→    if (advancedFilters.agentId) {
   187→      const agent = agents.find(a => a.id === parseInt(advancedFilters.agentId));
   188→      if (agent) filters.push({ key: 'agentId', label: `Agente: ${agent.name}` });
   189→    }
   190→
   191→    if (advancedFilters.campaignId) {
   192→      if (advancedFilters.campaignId === 'none') {
   193→        filters.push({ key: 'campaignId', label: 'Sin campaña' });
   194→      } else {
   195→        const campaign = campaigns.find(c => c.id === advancedFilters.campaignId);
   196→        if (campaign) filters.push({ key: 'campaignId', label: `Campaña: ${translateCampaignName(campaign.name)}` });
   197→      }
   198→    }
   199→
   200→    if (advancedFilters.phoneNumber) {
   201→      filters.push({ key: 'phoneNumber', label: `Teléfono: ${advancedFilters.phoneNumber}` });
   202→    }
   203→
   204→    if (advancedFilters.startDate) {
   205→      filters.push({ key: 'startDate', label: `Desde: ${new Date(advancedFilters.startDate).toLocaleDateString()}` });
   206→    }
   207→
   208→    if (advancedFilters.endDate) {
   209→      filters.push({ key: 'endDate', label: `Hasta: ${new Date(advancedFilters.endDate).toLocaleDateString()}` });
   210→    }
   211→
   212→    return filters;
   213→  };
   214→
   215→  // Remove a specific filter
   216→  const handleRemoveFilter = (key) => {
   217→    const newFilters = { ...advancedFilters };
   218→    if (key === 'startDate' || key === 'endDate') {
   219→      newFilters[key] = '';
   220→    } else {
   221→      newFilters[key] = '';
   222→    }
   223→    setAdvancedFilters(newFilters);
   224→    onFilterChange(newFilters);
   225→  };
   226→
   227→  const activeFilters = getActiveFilters();
   228→
   229→  if (loading && conversations.length === 0) {
   230→    return (
   231→      <div className="conversation-history-container">
   232→        <div className="loading-state">
   233→          <Spinner animation="border" variant="primary" />
   234→          <p className="mt-3">Cargando historial de conversaciones...</p>
   235→        </div>
   236→      </div>
   237→    );
   238→  }
   239→
   240→  const currentPage = Math.floor(pagination.offset / pagination.limit) + 1;
   241→
   242→  return (
   243→    <div className="conversation-history-container">
   244→      {/* Header with search and actions */}
   245→      <div className="conversation-history-header">
   246→        <div className="header-left">
   247→          <div className="search-box">
   248→            <i className="bi bi-search"></i>
   249→            <input
   250→              type="text"
   251→              placeholder="Buscar por número, nombre de contacto o mensaje..."
   252→              value={localSearch}
   253→              onChange={(e) => setLocalSearch(e.target.value)}
   254→            />
   255→          </div>
   256→          <button
   257→            className={`filter-btn ${activeFilterCount > 0 ? 'has-filters' : ''}`}
   258→            onClick={() => setShowAdvancedFilters(true)}
   259→          >
   260→            <i className="bi bi-funnel"></i>
   261→            <span>Filtros avanzados</span>
   262→            {activeFilterCount > 0 && <span className="filter-count">{activeFilterCount}</span>}
   263→          </button>
   264→        </div>
   265→        <div className="header-right">
   266→          <button className="export-button" onClick={onExport}>
   267→            <i className="bi bi-download"></i>
   268→            <span>Exportar</span>
   269→          </button>
   270→        </div>
   271→      </div>
   272→
   273→      {/* Active filters chips */}
   274→      {activeFilters.length > 0 && (
   275→        <div className="active-filters">
   276→          <span className="active-filters-label">Filtros activos:</span>
   277→          <div className="filter-chips">
   278→            {activeFilters.map((filter) => (
   279→              <div key={filter.key} className="filter-chip">
   280→                <span>{filter.label}</span>
   281→                <button
   282→                  onClick={() => handleRemoveFilter(filter.key)}
   283→                  className="remove-filter-btn"
   284→                  aria-label={`Remover filtro ${filter.label}`}
   285→                >
   286→                  <i className="bi bi-x"></i>
   287→                </button>
   288→              </div>
   289→            ))}
   290→            <button
   291→              onClick={handleClearAdvancedFilters}
   292→              className="clear-all-filters-btn"
   293→            >
   294→              <i className="bi bi-x-circle"></i>
   295→              Limpiar todos
   296→            </button>
   297→          </div>
   298→        </div>
   299→      )}
   300→
   301→      {/* Statistics banner */}
   302→      {pagination.total > 0 && (
   303→        <div className="statistics-banner">
   304→          <div className="stat-item">
   305→            <i className="bi bi-chat-dots"></i>
   306→            <span>
   307→              <strong>{pagination.total}</strong> conversaciones
   308→            </span>
   309→          </div>
   310→          <div className="stat-item">
   311→            <i className="bi bi-clock-history"></i>
   312→            <span>
   313→              Mostrando {Math.min(pagination.offset + 1, pagination.total)} -{' '}
   314→              {Math.min(pagination.offset + pagination.limit, pagination.total)}
   315→            </span>
   316→          </div>
   317→        </div>
   318→      )}
   319→
   320→      {/* List of conversations */}
   321→      <div className="conversation-history-content">
   322→        {conversations.length === 0 ? (
   323→          <div className="empty-state">
   324→            <i className="bi bi-clock-history display-1"></i>
   325→            <h5 className="mt-3">No se encontraron conversaciones</h5>
   326→            <p className="text-muted">
   327→              {localSearch || activeFilterCount > 0
   328→                ? 'Intenta ajustar los filtros de búsqueda'
   329→                : 'No hay conversaciones registradas en el sistema'}
   330→            </p>
   331→          </div>
   332→        ) : (
   333→          conversations.map((conversation) => (
   334→            <div key={conversation.conversationId} className="conversation-card">
   335→              <div className="conversation-card-header">
   336→                <div className="conversation-header-left">
   337→                  <div className="phone-number-badge">
   338→                    <i className="bi bi-telephone"></i>
   339→                    <span>{formatPhoneNumber(conversation.phoneNumber)}</span>
   340→                  </div>
   341→                  <div className="conversation-meta">
   342→                    {conversation.lead && (
   343→                      <span className="lead-name">
   344→                        <i className="bi bi-person"></i>
   345→                        {conversation.lead.name}
   346→                      </span>
   347→                    )}
   348→                    {conversation.campaign && (
   349→                      <Badge bg="info" className="campaign-badge">
   350→                        <i className="bi bi-megaphone"></i>
   351→                        {translateCampaignName(conversation.campaign.name)}
   352→                      </Badge>
   353→                    )}
   354→                    {!conversation.campaign && (
   355→                      <Badge bg="secondary" className="campaign-badge">
   356→                        Sin campaña
   357→                      </Badge>
   358→                    )}
   359→                  </div>
   360→                </div>
   361→                <button
   362→                  className="view-detail-btn"
   363→                  onClick={() => onViewDetail(conversation.phoneNumber, conversation.lineId)}
   364→                  title="Ver detalle completo"
   365→                >
   366→                  <i className="bi bi-eye"></i>
   367→                </button>
   368→              </div>
   369→
   370→              <div className="conversation-card-content">
   371→                {/* Last message */}
   372→                <div className="last-message-section">
   373→                  <div className="message-header">
   374→                    <i className={`bi ${getDirectionIcon(conversation.lastMessage.direction)} ${getDirectionColor(conversation.lastMessage.direction)}`}></i>
   375→                    <span className="message-label">Último mensaje</span>
   376→                    <div className="message-badges">
   377→                      <span className="message-type-badge">{conversation.lastMessage.type}</span>
   378→                      {conversation.lastMessage.status && (
   379→                        <Badge bg={getStatusBadgeVariant(conversation.lastMessage.status)} className="message-status-badge">
   380→                          {getStatusText(conversation.lastMessage.status)}
   381→                        </Badge>
   382→                      )}
   383→                    </div>
   384→                  </div>
   385→                  <p className="message-content">{truncateMessage(conversation.lastMessage.content)}</p>
   386→                  <span className="message-date">{formatDate(conversation.lastMessageAt)}</span>
   387→                </div>
   388→
   389→                {/* Details grid */}
   390→                <div className="conversation-details-grid">
   391→                  <div className="detail-item">
   392→                    <i className="bi bi-building"></i>
   393→                    <div>
   394→                      <span className="detail-label">Línea telefónica</span>
   395→                      <span className="detail-value">{conversation.line?.name || 'N/A'}</span>
   396→                    </div>
   397→                  </div>
   398→
   399→                  <div className="detail-item">
   400→                    <i className={`bi bi-person-badge ${!conversation.assignedUsers ? 'text-muted' : ''}`}></i>
   401→                    <div>
   402→                      <span className="detail-label">
   403→                        {conversation.assignedUsers && conversation.assignedUsers.length > 1
   404→                          ? 'Agentes asignados'
   405→                          : 'Agente asignado'}
   406→                      </span>
   407→                      {conversation.assignedUsers && conversation.assignedUsers.length > 0 ? (
   408→                        <span className="detail-value">
   409→                          {conversation.assignedUsers.map((user, index) => (
   410→                            <span key={user.id}>
   411→                              {user.name}{index < conversation.assignedUsers.length - 1 ? ', ' : ''}
   412→                            </span>
   413→                          ))}
   414→                        </span>
   415→                      ) : (
   416→                        <span className="detail-value text-muted">No asignado</span>
   417→                      )}
   418→                    </div>
   419→                  </div>
   420→
   421→                  <div className="detail-item">
   422→                    <i className="bi bi-calendar-event"></i>
   423→                    <div>
   424→                      <span className="detail-label">Primera interacción</span>
   425→                      <span className="detail-value">{formatDate(conversation.firstMessageAt)}</span>
   426→                    </div>
   427→                  </div>
   428→
   429→                  <div className="detail-item">
   430→                    <i className="bi bi-bar-chart"></i>
   431→                    <div>
   432→                      <span className="detail-label">Estadísticas</span>
   433→                      <div className="statistics-inline">
   434→                        <span className="stat-badge">
   435→                          <i className="bi bi-chat-dots"></i>
   436→                          {conversation.statistics.totalMessages}
   437→                        </span>
   438→                        <span className="stat-badge text-primary">
   439→                          <i className="bi bi-arrow-down-left"></i>
   440→                          {conversation.statistics.incomingMessages}
   441→                        </span>
   442→                        <span className="stat-badge text-success">
   443→                          <i className="bi bi-arrow-up-right"></i>
   444→                          {conversation.statistics.outgoingMessages}
   445→                        </span>
   446→                        {conversation.statistics.unreadMessages > 0 && (
   447→                          <span className="stat-badge text-danger">
   448→                            <i className="bi bi-envelope"></i>
   449→                            {conversation.statistics.unreadMessages} sin leer
   450→                          </span>
   451→                        )}
   452→                      </div>
   453→                    </div>
   454→                  </div>
   455→                </div>
   456→              </div>
   457→            </div>
   458→          ))
   459→        )}
   460→      </div>
   461→
   462→      {/* Pagination */}
   463→      {pagination.totalPages > 1 && (
   464→        <div className="pagination-container">
   465→          <button
   466→            className="pagination-btn"
   467→            onClick={() => onPageChange(currentPage - 1)}
   468→            disabled={currentPage === 1}
   469→          >
   470→            <i className="bi bi-chevron-left"></i>
   471→            Anterior
   472→          </button>
   473→          <span className="pagination-info">
   474→            Página {currentPage} de {pagination.totalPages}
   475→          </span>
   476→          <button
   477→            className="pagination-btn"
   478→            onClick={() => onPageChange(currentPage + 1)}
   479→            disabled={currentPage === pagination.totalPages}
   480→          >
   481→            Siguiente
   482→            <i className="bi bi-chevron-right"></i>
   483→          </button>
   484→        </div>
   485→      )}
   486→
   487→      {/* Advanced Filters Modal */}
   488→      <Modal
   489→        show={showAdvancedFilters}
   490→        onHide={() => setShowAdvancedFilters(false)}
   491→        size="lg"
   492→        centered
   493→      >
   494→        <Modal.Header closeButton>
   495→          <Modal.Title>Filtros avanzados</Modal.Title>
   496→        </Modal.Header>
   497→        <Modal.Body>
   498→          <div className="advanced-filters-form">
   499→            {/* Line filter */}
   500→            <div className="form-group">
   501→              <label htmlFor="lineFilter">Línea telefónica</label>
   502→              <select
   503→                id="lineFilter"
   504→                className="form-control"
   505→                value={advancedFilters.lineId}
   506→                onChange={(e) => setAdvancedFilters({ ...advancedFilters, lineId: e.target.value })}
   507→              >
   508→                <option value="">Todas las líneas</option>
   509→                {phoneLines.map((line) => (
   510→                  <option key={line.id} value={line.id}>
   511→                    {line.name} ({line.phone_number})
   512→                  </option>
   513→                ))}
   514→              </select>
   515→            </div>
   516→
   517→            {/* Agent filter */}
   518→            <div className="form-group">
   519→              <label htmlFor="agentFilter">Agente asignado</label>
   520→              <select
   521→                id="agentFilter"
   522→                className="form-control"
   523→                value={advancedFilters.agentId}
   524→                onChange={(e) => setAdvancedFilters({ ...advancedFilters, agentId: e.target.value })}
   525→              >
   526→                <option value="">Todos los agentes</option>
   527→                {agents.map((agent) => (
   528→                  <option key={agent.id} value={agent.id}>
   529→                    {agent.name}
   530→                  </option>
   531→                ))}
   532→              </select>
   533→            </div>
   534→
   535→            {/* Campaign filter */}
   536→            <div className="form-group">
   537→              <label htmlFor="campaignFilter">Campaña</label>
   538→              <select
   539→                id="campaignFilter"
   540→                className="form-control"
   541→                value={advancedFilters.campaignId}
   542→                onChange={(e) => setAdvancedFilters({ ...advancedFilters, campaignId: e.target.value })}
   543→              >
   544→                <option value="">Todas las campañas</option>
   545→                <option value="none">Sin campaña</option>
   546→                {campaigns.map((campaign) => (
   547→                  <option key={campaign.id} value={campaign.id}>
   548→                    {translateCampaignName(campaign.name)}
   549→                  </option>
   550→                ))}
   551→              </select>
   552→            </div>
   553→
   554→            {/* Phone number filter */}
   555→            <div className="form-group">
   556→              <label htmlFor="phoneNumberFilter">Número de teléfono</label>
   557→              <input
   558→                type="text"
   559→                id="phoneNumberFilter"
   560→                className="form-control"
   561→                placeholder="Ej: +52 1234567890"
   562→                value={advancedFilters.phoneNumber}
   563→                onChange={(e) => setAdvancedFilters({ ...advancedFilters, phoneNumber: e.target.value })}
   564→              />
   565→            </div>
   566→
   567→            {/* Date range */}
   568→            <div className="form-row">
   569→              <div className="form-group col-md-6">
   570→                <label htmlFor="startDate">Fecha de inicio</label>
   571→                <input
   572→                  type="date"
   573→                  id="startDate"
   574→                  className="form-control"
   575→                  value={advancedFilters.startDate}
   576→                  onChange={(e) => setAdvancedFilters({ ...advancedFilters, startDate: e.target.value })}
   577→                />
   578→              </div>
   579→              <div className="form-group col-md-6">
   580→                <label htmlFor="endDate">Fecha de fin</label>
   581→                <input
   582→                  type="date"
   583→                  id="endDate"
   584→                  className="form-control"
   585→                  value={advancedFilters.endDate}
   586→                  onChange={(e) => setAdvancedFilters({ ...advancedFilters, endDate: e.target.value })}
   587→                />
   588→              </div>
   589→            </div>
   590→
   591→            {/* Sort options */}
   592→            <div className="form-row">
   593→              <div className="form-group col-md-6">
   594→                <label htmlFor="sortBy">Ordenar por</label>
   595→                <select
   596→                  id="sortBy"
   597→                  className="form-control"
   598→                  value={advancedFilters.sortBy}
   599→                  onChange={(e) => setAdvancedFilters({ ...advancedFilters, sortBy: e.target.value })}
   600→                >
   601→                  <option value="last_message_at">Último mensaje</option>
