/**
 * Conversation History Table Component
 *
 * Displays conversation history in a card-based format with advanced filtering
 */

import { useState, useEffect } from 'react';
import { Spinner, Badge, Modal, Button } from 'react-bootstrap';
import PropTypes from 'prop-types';
import './ConversationHistoryTable.scss';

const ConversationHistoryTable = ({
  conversations,
  loading,
  phoneLines,
  agents,
  campaigns,
  filters,
  pagination,
  onFilterChange,
  onPageChange,
  onViewDetail,
  onExport,
}) => {
  const [localSearch, setLocalSearch] = useState(filters.search || '');
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);

  // Local state for advanced filters
  const [advancedFilters, setAdvancedFilters] = useState({
    lineId: filters.lineId || '',
    agentId: filters.agentId || '',
    campaignId: filters.campaignId || '',
    phoneNumber: filters.phoneNumber || '',
    startDate: filters.startDate || '',
    endDate: filters.endDate || '',
    sortBy: filters.sortBy || 'last_message_at',
    sortOrder: filters.sortOrder || 'DESC',
  });

  // Format date for display
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    const date = new Date(dateString);
    return date.toLocaleString('es-ES', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  // Format phone number for display
  const formatPhoneNumber = (phoneNumber) => {
    if (!phoneNumber) return 'N/A';
    // Remove non-digits and format as: +XX XXXXXXXXXX (only space after country code)
    const cleaned = phoneNumber.replace(/\D/g, '');
    if (cleaned.length === 12) {
      return `+${cleaned.slice(0, 2)} ${cleaned.slice(2)}`;
    }
    return phoneNumber;
  };

  // Get message direction icon
  const getDirectionIcon = (direction) => {
    return direction === 'incoming' ? 'bi-arrow-down-left' : 'bi-arrow-up-right';
  };

  // Get message direction color
  const getDirectionColor = (direction) => {
    return direction === 'incoming' ? 'text-primary' : 'text-success';
  };

  // Truncate message content
  const truncateMessage = (content, maxLength = 80) => {
    if (!content) return 'Sin contenido';
    if (content.length <= maxLength) return content;
    return content.substring(0, maxLength) + '...';
  };

  // Get status badge variant
  const getStatusBadgeVariant = (status) => {
    const statusMap = {
      sent: 'primary',
      delivered: 'success',
      read: 'info',
      failed: 'danger',
      received: 'secondary',
      pending: 'warning',
    };
    return statusMap[status] || 'secondary';
  };

  // Get status text in Spanish
  const getStatusText = (status) => {
    const statusMap = {
      sent: 'Enviado',
      delivered: 'Entregado',
      read: 'Leído',
      failed: 'Fallido',
      received: 'Recibido',
      pending: 'Pendiente',
    };
    return statusMap[status] || status;
  };

  // Translate campaign name to Spanish
  const translateCampaignName = (campaignName) => {
    if (!campaignName) return campaignName;

    // Common translations (handle both upper and lower case variations)
    const translations = {
      'schedule campaign': 'Campaña programada',
      'scheduled campaign': 'Campaña programada',
      'scheduled_campaign': 'Campaña programada',
      'schedule_campaign': 'Campaña programada',
      'schedule': 'Programada',
    };

    // Check for exact matches (case insensitive)
    const lowerName = campaignName.toLowerCase();
    for (const [key, value] of Object.entries(translations)) {
      if (lowerName === key) {
        return value;
      }
    }

    // Check for partial matches and replace
    let translatedName = campaignName;
    for (const [key, value] of Object.entries(translations)) {
      const regex = new RegExp(key, 'gi');
      if (regex.test(translatedName)) {
        translatedName = translatedName.replace(regex, value);
      }
    }

    return translatedName;
  };

  // Handle search input with debounce
  useEffect(() => {
    const timer = setTimeout(() => {
      onFilterChange({ search: localSearch });
    }, 500);

    return () => clearTimeout(timer);
  }, [localSearch]);

  // Apply advanced filters
  const handleApplyAdvancedFilters = () => {
    onFilterChange(advancedFilters);
    setShowAdvancedFilters(false);
  };

  // Clear advanced filters
  const handleClearAdvancedFilters = () => {
    const clearedFilters = {
      lineId: '',
      agentId: '',
      campaignId: '',
      phoneNumber: '',
      startDate: '',
      endDate: '',
      sortBy: 'last_message_at',
      sortOrder: 'DESC',
    };
    setAdvancedFilters(clearedFilters);
    onFilterChange(clearedFilters);
    setShowAdvancedFilters(false);
  };

  // Count active filters
  const activeFilterCount = Object.values(advancedFilters).filter(
    (value) => value && value !== 'last_message_at' && value !== 'DESC'
  ).length;

  // Get active filter labels
  const getActiveFilters = () => {
    const filters = [];

    if (advancedFilters.lineId) {
      const line = phoneLines.find(l => l.id === parseInt(advancedFilters.lineId));
      if (line) filters.push({ key: 'lineId', label: `Línea: ${line.name}` });
    }

    if (advancedFilters.agentId) {
      const agent = agents.find(a => a.id === parseInt(advancedFilters.agentId));
      if (agent) filters.push({ key: 'agentId', label: `Agente: ${agent.name}` });
    }

    if (advancedFilters.campaignId) {
      if (advancedFilters.campaignId === 'none') {
        filters.push({ key: 'campaignId', label: 'Sin campaña' });
      } else {
        const campaign = campaigns.find(c => c.id === advancedFilters.campaignId);
        if (campaign) filters.push({ key: 'campaignId', label: `Campaña: ${translateCampaignName(campaign.name)}` });
      }
    }

    if (advancedFilters.phoneNumber) {
      filters.push({ key: 'phoneNumber', label: `Teléfono: ${advancedFilters.phoneNumber}` });
    }

    if (advancedFilters.startDate) {
      filters.push({ key: 'startDate', label: `Desde: ${new Date(advancedFilters.startDate).toLocaleDateString()}` });
    }

    if (advancedFilters.endDate) {
      filters.push({ key: 'endDate', label: `Hasta: ${new Date(advancedFilters.endDate).toLocaleDateString()}` });
    }

    return filters;
  };

  // Remove a specific filter
  const handleRemoveFilter = (key) => {
    const newFilters = { ...advancedFilters };
    if (key === 'startDate' || key === 'endDate') {
      newFilters[key] = '';
    } else {
      newFilters[key] = '';
    }
    setAdvancedFilters(newFilters);
    onFilterChange(newFilters);
  };

  const activeFilters = getActiveFilters();

  if (loading && conversations.length === 0) {
    return (
      <div className="conversation-history-container">
        <div className="loading-state">
          <Spinner animation="border" variant="primary" />
          <p className="mt-3">Cargando historial de conversaciones...</p>
        </div>
      </div>
    );
  }

  const currentPage = Math.floor(pagination.offset / pagination.limit) + 1;

  return (
    <div className="conversation-history-container">
      {/* Header with search and actions */}
      <div className="conversation-history-header">
        <div className="header-left">
          <div className="search-box">
            <i className="bi bi-search"></i>
            <input
              type="text"
              placeholder="Buscar por número, nombre de contacto o mensaje..."
              value={localSearch}
              onChange={(e) => setLocalSearch(e.target.value)}
            />
          </div>
          <button
            className={`filter-btn ${activeFilterCount > 0 ? 'has-filters' : ''}`}
            onClick={() => setShowAdvancedFilters(true)}
          >
            <i className="bi bi-funnel"></i>
            <span>Filtros avanzados</span>
            {activeFilterCount > 0 && <span className="filter-count">{activeFilterCount}</span>}
          </button>
        </div>
        <div className="header-right">
          <button className="export-button" onClick={onExport}>
            <i className="bi bi-download"></i>
            <span>Exportar</span>
          </button>
        </div>
      </div>

      {/* Active filters chips */}
      {activeFilters.length > 0 && (
        <div className="active-filters">
          <span className="active-filters-label">Filtros activos:</span>
          <div className="filter-chips">
            {activeFilters.map((filter) => (
              <div key={filter.key} className="filter-chip">
                <span>{filter.label}</span>
                <button
                  onClick={() => handleRemoveFilter(filter.key)}
                  className="remove-filter-btn"
                  aria-label={`Remover filtro ${filter.label}`}
                >
                  <i className="bi bi-x"></i>
                </button>
              </div>
            ))}
            <button
              onClick={handleClearAdvancedFilters}
              className="clear-all-filters-btn"
            >
              <i className="bi bi-x-circle"></i>
              Limpiar todos
            </button>
          </div>
        </div>
      )}

      {/* Statistics banner */}
      {pagination.total > 0 && (
        <div className="statistics-banner">
          <div className="stat-item">
            <i className="bi bi-chat-dots"></i>
            <span>
              <strong>{pagination.total}</strong> conversaciones
            </span>
          </div>
          <div className="stat-item">
            <i className="bi bi-clock-history"></i>
            <span>
              Mostrando {Math.min(pagination.offset + 1, pagination.total)} -{' '}
              {Math.min(pagination.offset + pagination.limit, pagination.total)}
            </span>
          </div>
        </div>
      )}

      {/* List of conversations */}
      <div className="conversation-history-content">
        {conversations.length === 0 ? (
          <div className="empty-state">
            <i className="bi bi-clock-history display-1"></i>
            <h5 className="mt-3">No se encontraron conversaciones</h5>
            <p className="text-muted">
              {localSearch || activeFilterCount > 0
                ? 'Intenta ajustar los filtros de búsqueda'
                : 'No hay conversaciones registradas en el sistema'}
            </p>
          </div>
        ) : (
          conversations.map((conversation) => (
            <div key={conversation.conversationId} className="conversation-card">
              <div className="conversation-card-header">
                <div className="conversation-header-left">
                  <div className="phone-number-badge">
                    <i className="bi bi-telephone"></i>
                    <span>{formatPhoneNumber(conversation.phoneNumber)}</span>
                  </div>
                  <div className="conversation-meta">
                    {conversation.lead && (
                      <span className="lead-name">
                        <i className="bi bi-person"></i>
                        {conversation.lead.name}
                      </span>
                    )}
                    {conversation.campaign && (
                      <Badge bg="info" className="campaign-badge">
                        <i className="bi bi-megaphone"></i>
                        {translateCampaignName(conversation.campaign.name)}
                      </Badge>
                    )}
                    {!conversation.campaign && (
                      <Badge bg="secondary" className="campaign-badge">
                        Sin campaña
                      </Badge>
                    )}
                  </div>
                </div>
                <button
                  className="view-detail-btn"
                  onClick={() => onViewDetail(conversation.phoneNumber, conversation.lineId)}
                  title="Ver detalle completo"
                >
                  <i className="bi bi-eye"></i>
                </button>
              </div>

              <div className="conversation-card-content">
                {/* Last message */}
                <div className="last-message-section">
                  <div className="message-header">
                    <i className={`bi ${getDirectionIcon(conversation.lastMessage.direction)} ${getDirectionColor(conversation.lastMessage.direction)}`}></i>
                    <span className="message-label">Último mensaje</span>
                    <div className="message-badges">
                      <span className="message-type-badge">{conversation.lastMessage.type}</span>
                      {conversation.lastMessage.status && (
                        <Badge bg={getStatusBadgeVariant(conversation.lastMessage.status)} className="message-status-badge">
                          {getStatusText(conversation.lastMessage.status)}
                        </Badge>
                      )}
                    </div>
                  </div>
                  <p className="message-content">{truncateMessage(conversation.lastMessage.content)}</p>
                  <span className="message-date">{formatDate(conversation.lastMessageAt)}</span>
                </div>

                {/* Details grid */}
                <div className="conversation-details-grid">
                  <div className="detail-item">
                    <i className="bi bi-building"></i>
                    <div>
                      <span className="detail-label">Línea telefónica</span>
                      <span className="detail-value">{conversation.line?.name || 'N/A'}</span>
                    </div>
                  </div>

                  <div className="detail-item">
                    <i className={`bi bi-person-badge ${!conversation.assignedUsers ? 'text-muted' : ''}`}></i>
                    <div>
                      <span className="detail-label">
                        {conversation.assignedUsers && conversation.assignedUsers.length > 1
                          ? 'Agentes asignados'
                          : 'Agente asignado'}
                      </span>
                      {conversation.assignedUsers && conversation.assignedUsers.length > 0 ? (
                        <span className="detail-value">
                          {conversation.assignedUsers.map((user, index) => (
                            <span key={user.id}>
                              {user.name}{index < conversation.assignedUsers.length - 1 ? ', ' : ''}
                            </span>
                          ))}
                        </span>
                      ) : (
                        <span className="detail-value text-muted">No asignado</span>
                      )}
                    </div>
                  </div>

                  <div className="detail-item">
                    <i className="bi bi-calendar-event"></i>
                    <div>
                      <span className="detail-label">Primera interacción</span>
                      <span className="detail-value">{formatDate(conversation.firstMessageAt)}</span>
                    </div>
                  </div>

                  <div className="detail-item">
                    <i className="bi bi-bar-chart"></i>
                    <div>
                      <span className="detail-label">Estadísticas</span>
                      <div className="statistics-inline">
                        <span className="stat-badge">
                          <i className="bi bi-chat-dots"></i>
                          {conversation.statistics.totalMessages}
                        </span>
                        <span className="stat-badge text-primary">
                          <i className="bi bi-arrow-down-left"></i>
                          {conversation.statistics.incomingMessages}
                        </span>
                        <span className="stat-badge text-success">
                          <i className="bi bi-arrow-up-right"></i>
                          {conversation.statistics.outgoingMessages}
                        </span>
                        {conversation.statistics.unreadMessages > 0 && (
                          <span className="stat-badge text-danger">
                            <i className="bi bi-envelope"></i>
                            {conversation.statistics.unreadMessages} sin leer
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Pagination */}
      {pagination.totalPages > 1 && (
        <div className="pagination-container">
          <button
            className="pagination-btn"
            onClick={() => onPageChange(currentPage - 1)}
            disabled={currentPage === 1}
          >
            <i className="bi bi-chevron-left"></i>
            Anterior
          </button>
          <span className="pagination-info">
            Página {currentPage} de {pagination.totalPages}
          </span>
          <button
            className="pagination-btn"
            onClick={() => onPageChange(currentPage + 1)}
            disabled={currentPage === pagination.totalPages}
          >
            Siguiente
            <i className="bi bi-chevron-right"></i>
          </button>
        </div>
      )}

      {/* Advanced Filters Modal */}
      <Modal
        show={showAdvancedFilters}
        onHide={() => setShowAdvancedFilters(false)}
        size="lg"
        centered
      >
        <Modal.Header closeButton>
          <Modal.Title>Filtros avanzados</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <div className="advanced-filters-form">
            {/* Line filter */}
            <div className="form-group">
              <label htmlFor="lineFilter">Línea telefónica</label>
              <select
                id="lineFilter"
                className="form-control"
                value={advancedFilters.lineId}
                onChange={(e) => setAdvancedFilters({ ...advancedFilters, lineId: e.target.value })}
              >
                <option value="">Todas las líneas</option>
                {phoneLines.map((line) => (
                  <option key={line.id} value={line.id}>
                    {line.name} ({line.phone_number})
                  </option>
                ))}
              </select>
            </div>

            {/* Agent filter */}
            <div className="form-group">
              <label htmlFor="agentFilter">Agente asignado</label>
              <select
                id="agentFilter"
                className="form-control"
                value={advancedFilters.agentId}
                onChange={(e) => setAdvancedFilters({ ...advancedFilters, agentId: e.target.value })}
              >
                <option value="">Todos los agentes</option>
                {agents.map((agent) => (
                  <option key={agent.id} value={agent.id}>
                    {agent.name}
                  </option>
                ))}
              </select>
            </div>

            {/* Campaign filter */}
            <div className="form-group">
              <label htmlFor="campaignFilter">Campaña</label>
              <select
                id="campaignFilter"
                className="form-control"
                value={advancedFilters.campaignId}
                onChange={(e) => setAdvancedFilters({ ...advancedFilters, campaignId: e.target.value })}
              >
                <option value="">Todas las campañas</option>
                <option value="none">Sin campaña</option>
                {campaigns.map((campaign) => (
                  <option key={campaign.id} value={campaign.id}>
                    {translateCampaignName(campaign.name)}
                  </option>
                ))}
              </select>
            </div>

            {/* Phone number filter */}
            <div className="form-group">
              <label htmlFor="phoneNumberFilter">Número de teléfono</label>
              <input
                type="text"
                id="phoneNumberFilter"
                className="form-control"
                placeholder="Ej: +52 1234567890"
                value={advancedFilters.phoneNumber}
                onChange={(e) => setAdvancedFilters({ ...advancedFilters, phoneNumber: e.target.value })}
              />
            </div>

            {/* Date range */}
            <div className="form-row">
              <div className="form-group col-md-6">
                <label htmlFor="startDate">Fecha de inicio</label>
                <input
                  type="date"
                  id="startDate"
                  className="form-control"
                  value={advancedFilters.startDate}
                  onChange={(e) => setAdvancedFilters({ ...advancedFilters, startDate: e.target.value })}
                />
              </div>
              <div className="form-group col-md-6">
                <label htmlFor="endDate">Fecha de fin</label>
                <input
                  type="date"
                  id="endDate"
                  className="form-control"
                  value={advancedFilters.endDate}
                  onChange={(e) => setAdvancedFilters({ ...advancedFilters, endDate: e.target.value })}
                />
              </div>
            </div>

            {/* Sort options */}
            <div className="form-row">
              <div className="form-group col-md-6">
                <label htmlFor="sortBy">Ordenar por</label>
                <select
                  id="sortBy"
                  className="form-control"
                  value={advancedFilters.sortBy}
                  onChange={(e) => setAdvancedFilters({ ...advancedFilters, sortBy: e.target.value })}
                >
                  <option value="last_message_at">Último mensaje</option>
                  <option value="first_message_at">Primer mensaje</option>
                  <option value="total_messages">Total de mensajes</option>
                </select>
              </div>
              <div className="form-group col-md-6">
                <label htmlFor="sortOrder">Orden</label>
                <select
                  id="sortOrder"
                  className="form-control"
                  value={advancedFilters.sortOrder}
                  onChange={(e) => setAdvancedFilters({ ...advancedFilters, sortOrder: e.target.value })}
                >
                  <option value="DESC">Descendente</option>
                  <option value="ASC">Ascendente</option>
                </select>
              </div>
            </div>
          </div>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="outline-secondary" onClick={handleClearAdvancedFilters}>
            Limpiar filtros
          </Button>
          <Button variant="primary" onClick={handleApplyAdvancedFilters}>
            Aplicar filtros
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

ConversationHistoryTable.propTypes = {
  conversations: PropTypes.array.isRequired,
  loading: PropTypes.bool,
  phoneLines: PropTypes.array,
  agents: PropTypes.array,
  campaigns: PropTypes.array,
  filters: PropTypes.object,
  pagination: PropTypes.object,
  onFilterChange: PropTypes.func.isRequired,
  onPageChange: PropTypes.func.isRequired,
  onViewDetail: PropTypes.func,
  onExport: PropTypes.func,
};

ConversationHistoryTable.defaultProps = {
  loading: false,
  phoneLines: [],
  agents: [],
  campaigns: [],
  filters: {},
  pagination: { total: 0, limit: 20, offset: 0, totalPages: 0 },
  onViewDetail: () => {},
  onExport: () => {},
};

export default ConversationHistoryTable;

