/**
 * Conversation History Page
 *
 * Page for viewing and analyzing historical conversations
 * with advanced filtering capabilities
 */

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Alert, Modal, Button } from 'react-bootstrap';
import ConversationHistoryTable from '../../components/conversation-history/ConversationHistoryTable';
import useConversationHistoryStore from '../../store/conversationHistoryStore';
import usePhoneLinesStore from '../../store/phoneLinesStore';
import useUsersStore from '../../store/usersStore';
import useConversationsStore from '../../store/conversationsStore';
import useAuthStore from '../../store/authStore';
import './ConversationHistory.scss';

const ConversationHistory = () => {
  const navigate = useNavigate();
  const { user } = useAuthStore();

  const {
    conversations,
    selectedConversation,
    campaigns,
    loading,
    error,
    filters,
    pagination,
    fetchConversationHistory,
    fetchConversationDetail,
    fetchCampaigns,
    setFilters,
    goToPage,
    exportConversationHistory,
    clearError,
    clearSelectedConversation,
  } = useConversationHistoryStore();

  const { phoneLines, fetchPhoneLines } = usePhoneLinesStore();
  const { users, fetchUsers } = useUsersStore();
  const { switchConversation } = useConversationsStore();

  const [showDetailModal, setShowDetailModal] = useState(false);
  const [exportSuccess, setExportSuccess] = useState(false);

  // Fetch initial data
  useEffect(() => {
    fetchConversationHistory();
    fetchPhoneLines();
    fetchUsers();
    fetchCampaigns();
  }, []);

  // Filter agents from users
  const agents = users.filter((user) => user.role === 'agent' || user.role === 'admin');

  // Handle filter changes
  const handleFilterChange = (newFilters) => {
    setFilters(newFilters);
    fetchConversationHistory();
  };

  // Handle page change
  const handlePageChange = (page) => {
    goToPage(page);
  };

  // Handle view detail - Navigate to chat with pre-selected conversation
  const handleViewDetail = async (phoneNumber, lineId) => {
    try {
      // Get the full conversation detail
      await fetchConversationDetail(phoneNumber, lineId);

      // Navigate to chat with state containing the conversation to open
      const chatRoute = user?.role === 'admin' ? '/admin/chat' : '/agent/chat';
      navigate(chatRoute, {
        state: {
          preSelectedConversation: {
            phone_number: phoneNumber,
            line_id: lineId,
          }
        }
      });
    } catch (err) {
      console.error('Error viewing conversation detail:', err);
    }
  };

  // Handle close detail modal
  const handleCloseDetailModal = () => {
    setShowDetailModal(false);
    clearSelectedConversation();
  };

  // Handle export
  const handleExport = async () => {
    try {
      await exportConversationHistory();
      setExportSuccess(true);
      setTimeout(() => setExportSuccess(false), 3000);
    } catch (err) {
      console.error('Export error:', err);
    }
  };

  // Format date for display
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    const date = new Date(dateString);
    return date.toLocaleString('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  // Format phone number for display
  const formatPhoneNumber = (phoneNumber) => {
    if (!phoneNumber) return 'N/A';
    // Remove non-digits and format as: +XX XXXXXXXXXX (only space after country code)
    const cleaned = phoneNumber.replace(/\D/g, '');
    if (cleaned.length === 12) {
      return `+${cleaned.slice(0, 2)} ${cleaned.slice(2)}`;
    }
    return phoneNumber;
  };

  return (
    <div className="conversation-history-page">
      <div className="page-header">
        <div>
          <h1 className="page-title">Historial de Conversaciones</h1>
          <p className="page-subtitle">
            Vista histórica completa de todas las conversaciones organizadas por número, campaña y agente
          </p>
        </div>
      </div>

      {error && (
        <Alert variant="danger" dismissible onClose={clearError} className="mb-4">
          {error}
        </Alert>
      )}

      {exportSuccess && (
        <Alert variant="success" dismissible onClose={() => setExportSuccess(false)} className="mb-4">
          Historial exportado exitosamente
        </Alert>
      )}

      <ConversationHistoryTable
        conversations={conversations}
        loading={loading}
        phoneLines={phoneLines}
        agents={agents}
        campaigns={campaigns}
        filters={filters}
        pagination={pagination}
        onFilterChange={handleFilterChange}
        onPageChange={handlePageChange}
        onViewDetail={handleViewDetail}
        onExport={handleExport}
      />

      {/* Conversation Detail Modal */}
      <Modal
        show={showDetailModal}
        onHide={handleCloseDetailModal}
        size="xl"
        centered
        scrollable
      >
        <Modal.Header closeButton>
          <Modal.Title>
            Detalle de Conversación{' '}
            {selectedConversation && (
              <span className="text-muted">
                - {formatPhoneNumber(selectedConversation.phoneNumber)}
              </span>
            )}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedConversation ? (
            <div className="conversation-detail-container">
              {/* Conversation metadata */}
              <div className="conversation-metadata">
                <div className="metadata-section">
                  <h5>Información de contacto</h5>
                  <div className="metadata-grid">
                    <div className="metadata-item">
                      <strong>Número de teléfono:</strong>
                      <span>{formatPhoneNumber(selectedConversation.phoneNumber)}</span>
                    </div>
                    {selectedConversation.lead && (
                      <>
                        <div className="metadata-item">
                          <strong>Nombre:</strong>
                          <span>{selectedConversation.lead.name}</span>
                        </div>
                        {selectedConversation.lead.email && (
                          <div className="metadata-item">
                            <strong>Email:</strong>
                            <span>{selectedConversation.lead.email}</span>
                          </div>
                        )}
                        <div className="metadata-item">
                          <strong>Estado del lead:</strong>
                          <span className="text-capitalize">{selectedConversation.lead.status}</span>
                        </div>
                      </>
                    )}
                  </div>
                </div>

                <div className="metadata-section">
                  <h5>Información de asignación</h5>
                  <div className="metadata-grid">
                    <div className="metadata-item">
                      <strong>Línea telefónica:</strong>
                      <span>{selectedConversation.line?.name || 'N/A'}</span>
                    </div>
                    {selectedConversation.assignment?.assignedUser ? (
                      <>
                        <div className="metadata-item">
                          <strong>Agente asignado:</strong>
                          <span>{selectedConversation.assignment.assignedUser.name}</span>
                        </div>
                        <div className="metadata-item">
                          <strong>Fecha de asignación:</strong>
                          <span>{formatDate(selectedConversation.assignment.assignedAt)}</span>
                        </div>
                      </>
                    ) : (
                      <div className="metadata-item">
                        <strong>Agente asignado:</strong>
                        <span className="text-muted">No asignado</span>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {/* Messages timeline */}
              <div className="messages-timeline">
                <h5>Historial de mensajes ({selectedConversation.messages?.length || 0})</h5>
                <div className="timeline-container">
                  {selectedConversation.messages && selectedConversation.messages.length > 0 ? (
                    selectedConversation.messages.map((message) => (
                      <div
                        key={message.id}
                        className={`timeline-message ${message.direction}`}
                      >
                        <div className="message-header">
                          <span className="message-direction">
                            {message.direction === 'incoming' ? (
                              <>
                                <i className="bi bi-arrow-down-left text-primary"></i>
                                Entrante
                              </>
                            ) : (
                              <>
                                <i className="bi bi-arrow-up-right text-success"></i>
                                Saliente
                              </>
                            )}
                          </span>
                          <span className="message-date">{formatDate(message.created_at)}</span>
                        </div>
                        <div className="message-content">
                          <div className="message-type-badge">{message.message_type}</div>
                          <p>{message.message_content}</p>
                          {message.file_url && (
                            <div className="message-attachment">
                              <i className="bi bi-paperclip"></i>
                              <a href={message.file_url} target="_blank" rel="noopener noreferrer">
                                Ver archivo adjunto
                              </a>
                            </div>
                          )}
                        </div>
                        {message.sender && (
                          <div className="message-footer">
                            <span className="message-sender">
                              <i className="bi bi-person"></i>
                              Enviado por: {message.sender.name}
                            </span>
                          </div>
                        )}
                        <div className="message-status">
                          <span className={`status-badge status-${message.status}`}>
                            {message.status}
                          </span>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="empty-messages">
                      <i className="bi bi-chat-dots display-4 text-muted"></i>
                      <p className="text-muted">No hay mensajes en esta conversación</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ) : (
            <div className="text-center py-5">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Cargando...</span>
              </div>
            </div>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCloseDetailModal}>
            Cerrar
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default ConversationHistory;

