/**
 * Conversation History Service
 *
 * API calls for conversation history management
 * Provides historical view with advanced filtering
 */

import api from './api';

/**
 * Get conversation history with filters
 *
 * @param {Object} filters - Filter options
 * @param {number} filters.lineId - Filter by phone line ID
 * @param {number} filters.agentId - Filter by assigned agent ID
 * @param {string} filters.campaignId - Filter by campaign ID (use 'none' for no campaign)
 * @param {string} filters.phoneNumber - Filter by phone number (partial match)
 * @param {string} filters.search - Search in phone number, lead name, or message content
 * @param {string} filters.startDate - Filter from this date (ISO 8601)
 * @param {string} filters.endDate - Filter to this date (ISO 8601)
 * @param {string} filters.sortBy - Sort field (default: last_message_at)
 * @param {string} filters.sortOrder - Sort order (ASC/DESC, default: DESC)
 * @param {number} filters.limit - Results per page (default: 20)
 * @param {number} filters.offset - Pagination offset (default: 0)
 * @returns {Promise<Object>} Conversation history data
 */
export const getConversationHistory = async (filters = {}) => {
  try {
    const params = new URLSearchParams();

    if (filters.lineId) params.append('lineId', filters.lineId);
    if (filters.agentId) params.append('agentId', filters.agentId);
    if (filters.campaignId) params.append('campaignId', filters.campaignId);
    if (filters.phoneNumber) params.append('phoneNumber', filters.phoneNumber);
    if (filters.search) params.append('search', filters.search);
    if (filters.startDate) params.append('startDate', filters.startDate);
    if (filters.endDate) params.append('endDate', filters.endDate);
    if (filters.sortBy) params.append('sortBy', filters.sortBy);
    if (filters.sortOrder) params.append('sortOrder', filters.sortOrder);
    if (filters.limit) params.append('limit', filters.limit);
    if (filters.offset) params.append('offset', filters.offset);

    const response = await api.get(`/conversation-history?${params.toString()}`);
    return response.data;
  } catch (error) {
    console.error('[ConversationHistoryService] Error fetching conversation history:', error);
    throw error;
  }
};

/**
 * Get conversation detail by phone number and line ID
 *
 * @param {string} phoneNumber - Customer phone number
 * @param {number} lineId - Phone line ID
 * @returns {Promise<Object>} Detailed conversation data with all messages
 */
export const getConversationDetail = async (phoneNumber, lineId) => {
  try {
    const response = await api.get(`/conversation-history/${phoneNumber}/${lineId}`);
    return response.data;
  } catch (error) {
    console.error('[ConversationHistoryService] Error fetching conversation detail:', error);
    throw error;
  }
};

/**
 * Get list of all campaigns
 *
 * @returns {Promise<Array>} List of campaigns
 */
export const getCampaigns = async () => {
  try {
    const response = await api.get('/conversation-history/campaigns/list');
    return response.data;
  } catch (error) {
    console.error('[ConversationHistoryService] Error fetching campaigns:', error);
    throw error;
  }
};

/**
 * Export conversation history to CSV
 *
 * @param {Object} filters - Same filters as getConversationHistory
 * @returns {Promise<Blob>} CSV file blob
 */
export const exportConversationHistory = async (filters = {}) => {
  try {
    const params = new URLSearchParams();

    Object.keys(filters).forEach(key => {
      if (filters[key]) params.append(key, filters[key]);
    });

    const response = await api.get(`/conversation-history/export?${params.toString()}`, {
      responseType: 'blob',
    });

    return response.data;
  } catch (error) {
    console.error('[ConversationHistoryService] Error exporting conversation history:', error);
    throw error;
  }
};

export default {
  getConversationHistory,
  getConversationDetail,
  getCampaigns,
  exportConversationHistory,
};

