          model: 'whatsapp_lines',
          key: 'id',
        },
        onUpdate: 'CASCADE',
        onDelete: 'CASCADE',
        comment: 'WhatsApp line for this conversation',
      },
      assigned_user_id: {
        type: Sequelize.INTEGER,
        allowNull: true,
        references: {
          model: 'users',
          key: 'id',
        },
        onUpdate: 'CASCADE',
        onDelete: 'SET NULL',
        comment: 'Agent assigned to conversation (NULL if unassigned)',
      },
      assigned_at: {
        type: Sequelize.DATE,
        allowNull: true,
        comment: 'Assignment timestamp',
      },
      assigned_by_user_id: {
        type: Sequelize.INTEGER,
        allowNull: true,
        references: {
          model: 'users',
          key: 'id',
        },
        onUpdate: 'CASCADE',
        onDelete: 'SET NULL',
        comment: 'Admin/agent who made the assignment',
      },
    }, {
      charset: 'utf8mb4',
      collate: 'utf8mb4_unicode_ci',
      engine: 'InnoDB',
      comment: 'Conversation assignments to agents for workload distribution',
    });

    // Create indexes
    await queryInterface.addIndex('conversation_assignments', ['phone_number', 'line_id'], {
      name: 'idx_conversation_unique',
      unique: true,
    });

    await queryInterface.addIndex('conversation_assignments', ['assigned_user_id'], {
      name: 'idx_conversation_assigned_user',
    });

    await queryInterface.addIndex('conversation_assignments', ['line_id'], {
      name: 'idx_conversation_line',
    });

    await queryInterface.addIndex('conversation_assignments', ['phone_number'], {
      name: 'idx_conversation_phone',
    });
  },

  async down(queryInterface, Sequelize) {
    await queryInterface.dropTable('conversation_assignments');
  }
};

