'use strict';

/**
 * Migration: Add campaign_id to conversation_assignments table
 *
 * Adds campaign_id field to persist the original campaign context
 * for conversations, preventing them from becoming visible to all agents
 * after the 48-hour window expires.
 *
 * This ensures that conversations remain isolated to their original
 * campaign agents regardless of response time.
 *
 * @type {import('sequelize-cli').Migration}
 */
module.exports = {
  async up(queryInterface, Sequelize) {
    await queryInterface.addColumn('conversation_assignments', 'campaign_id', {
      type: Sequelize.STRING,
      allowNull: true,
      comment: 'Campaign ID from which this conversation originated (NULL for manual assignments)',
    });

    // Create index for campaign lookups
    await queryInterface.addIndex('conversation_assignments', ['campaign_id'], {
      name: 'idx_conversation_campaign',
    });

    // Create composite index for campaign + phone lookups
    await queryInterface.addIndex('conversation_assignments', ['campaign_id', 'phone_number'], {
      name: 'idx_conversation_campaign_phone',
    });
  },

  async down(queryInterface, Sequelize) {
    await queryInterface.removeIndex('conversation_assignments', 'idx_conversation_campaign_phone');
    await queryInterface.removeIndex('conversation_assignments', 'idx_conversation_campaign');
    await queryInterface.removeColumn('conversation_assignments', 'campaign_id');
  }
};

