/**
 * Conversation History Service
 *
 * Manages conversation history with advanced filtering
 * Provides historical view of all conversations organized by:
 * - Phone number
 * - Campaign
 * - Agent
 * - Phone line
 * - Date range
 */

import { Message, Lead, User, PhoneLine, ConversationAssignment } from '../models/sequelize/associations.js';
import { Op } from 'sequelize';
import sequelize from '../config/sequelize.js';
import ExcelJS from 'exceljs';

class ConversationHistoryService {
  /**
   * Get conversation history with advanced filters
   * @param {Object} filters - Filter options
   * @param {number} filters.userId - User ID (for agents, only their conversations)
   * @param {string} filters.userRole - User role (admin/agent)
   * @param {number} filters.lineId - Filter by phone line ID
   * @param {number} filters.agentId - Filter by assigned agent
   * @param {string} filters.campaignId - Filter by campaign ID
   * @param {string} filters.phoneNumber - Filter by phone number
   * @param {string} filters.search - Search in phone number, lead name, or message content
   * @param {Date} filters.startDate - Filter from this date
   * @param {Date} filters.endDate - Filter to this date
   * @param {string} filters.sortBy - Sort field (default: last_message_at)
   * @param {string} filters.sortOrder - Sort order (ASC/DESC, default: DESC)
   * @param {number} filters.limit - Results per page (default: 20, max: 100)
   * @param {number} filters.offset - Pagination offset (default: 0)
   * @returns {Promise<Object>} Conversation history with pagination
   */
  async getConversationHistory(filters = {}) {
    try {
      const {
        userId,
        userRole,
        lineId,
        agentId,
        campaignId,
        phoneNumber,
        search,
        startDate,
        endDate,
        sortBy = 'last_message_at',
        sortOrder = 'DESC',
        limit = 20,
        offset = 0,
        isExport = false,
      } = filters;

      // For exports, allow higher limits; otherwise cap at 100
      const validatedLimit = isExport
        ? (parseInt(limit) || 10000)
        : Math.min(parseInt(limit) || 20, 100);
      const validatedOffset = parseInt(offset) || 0;

      // Build WHERE conditions
      const whereConditions = ['m.deleted_at IS NULL'];
      const replacements = {};

      // If agent, filter by assigned lines
      if (userRole === 'agent') {
        const { default: PhoneLineAssignmentService } = await import('./PhoneLineAssignmentService.js');
        const assignments = await PhoneLineAssignmentService.getUserAssignedLines(userId);
        const assignedLineIds = assignments.map(a => a.line_id);

        if (assignedLineIds.length === 0) {
          return {
            conversations: [],
            total: 0,
            limit: validatedLimit,
            offset: validatedOffset,
          };
        }

        whereConditions.push('m.line_id IN (:assignedLineIds)');
        replacements.assignedLineIds = assignedLineIds;
      }

      // Filter by phone line
      if (lineId) {
        whereConditions.push('m.line_id = :lineId');
        replacements.lineId = parseInt(lineId);
      }

      // Filter by phone number
      if (phoneNumber) {
        whereConditions.push('m.phone_number LIKE :phoneNumber');
        replacements.phoneNumber = `%${phoneNumber}%`;
      }

      // Filter by campaign
      if (campaignId) {
        if (campaignId === 'none') {
          whereConditions.push('m.campaign_id IS NULL');
        } else {
          whereConditions.push('m.campaign_id = :campaignId');
          replacements.campaignId = campaignId;
        }
      }

      // Filter by date range
      if (startDate) {
        whereConditions.push('m.created_at >= :startDate');
        replacements.startDate = new Date(startDate);
      }

      if (endDate) {
        whereConditions.push('m.created_at <= :endDate');
        replacements.endDate = new Date(endDate);
      }

      // Search in phone number, lead name, or message content
      if (search) {
        // Remove spaces from search term for phone number comparison
        const searchNoSpaces = search.replace(/\s/g, '');

        whereConditions.push(`(
          REPLACE(m.phone_number, ' ', '') LIKE :searchNoSpaces
          OR m.message_content LIKE :search
          OR EXISTS (
            SELECT 1 FROM leads l
            WHERE l.phone_number = m.phone_number
            AND l.name LIKE :search
          )
        )`);
        replacements.search = `%${search}%`;
        replacements.searchNoSpaces = `%${searchNoSpaces}%`;
      }

      const whereClause = whereConditions.join(' AND ');

      // Build query to get conversation groups (grouped by phone_number and line_id only)
      // NOTE: We no longer group by campaign_id to avoid duplicate conversations
      // Instead, we show the campaign from the last message
      const conversationsQuery = `
        SELECT
          m.phone_number,
          m.line_id,
          MAX(m.created_at) as last_message_at,
          MIN(m.created_at) as first_message_at,
          COUNT(m.id) as total_messages,
          SUM(CASE WHEN m.direction = 'incoming' THEN 1 ELSE 0 END) as incoming_messages,
          SUM(CASE WHEN m.direction = 'outgoing' THEN 1 ELSE 0 END) as outgoing_messages,
          SUM(CASE WHEN m.direction = 'incoming' AND m.status = 'received' THEN 1 ELSE 0 END) as unread_messages,
          (
            SELECT message_content
            FROM messages
            WHERE phone_number = m.phone_number
              AND line_id = m.line_id
              AND deleted_at IS NULL
            ORDER BY created_at DESC
            LIMIT 1
          ) as last_message_content,
          (
            SELECT direction
            FROM messages
            WHERE phone_number = m.phone_number
              AND line_id = m.line_id
              AND deleted_at IS NULL
            ORDER BY created_at DESC
            LIMIT 1
          ) as last_message_direction,
          (
            SELECT message_type
            FROM messages
            WHERE phone_number = m.phone_number
              AND line_id = m.line_id
              AND deleted_at IS NULL
            ORDER BY created_at DESC
            LIMIT 1
          ) as last_message_type,
          (
            SELECT status
            FROM messages
            WHERE phone_number = m.phone_number
              AND line_id = m.line_id
              AND deleted_at IS NULL
            ORDER BY created_at DESC
            LIMIT 1
          ) as last_message_status,
          (
            SELECT campaign_id
            FROM messages
            WHERE phone_number = m.phone_number
              AND line_id = m.line_id
              AND deleted_at IS NULL
            ORDER BY created_at DESC
            LIMIT 1
          ) as campaign_id,
          (
            SELECT campaign_name
            FROM messages
            WHERE phone_number = m.phone_number
              AND line_id = m.line_id
              AND deleted_at IS NULL
            ORDER BY created_at DESC
            LIMIT 1
          ) as campaign_name,
          (
            SELECT l.id
            FROM leads l
            WHERE l.phone_number = m.phone_number
            LIMIT 1
          ) as lead_id,
          (
            SELECT l.name
            FROM leads l
            WHERE l.phone_number = m.phone_number
            LIMIT 1
          ) as lead_name,
          (
            SELECT l.email
            FROM leads l
            WHERE l.phone_number = m.phone_number
            LIMIT 1
          ) as lead_email,
          (
            SELECT l.status
            FROM leads l
            WHERE l.phone_number = m.phone_number
            LIMIT 1
          ) as lead_status,
          (
            SELECT pl.id
            FROM phone_lines pl
            WHERE pl.id = m.line_id
            LIMIT 1
          ) as line_id_ref,
          (
            SELECT pl.name
            FROM phone_lines pl
            WHERE pl.id = m.line_id
            LIMIT 1
          ) as line_name,
          (
            SELECT pl.phone_number
            FROM phone_lines pl
            WHERE pl.id = m.line_id
            LIMIT 1
          ) as line_phone_number,
          (
            SELECT GROUP_CONCAT(DISTINCT ca.assigned_user_id ORDER BY ca.assigned_at DESC)
            FROM conversation_assignments ca
            WHERE ca.phone_number = m.phone_number AND ca.line_id = m.line_id
          ) as assigned_user_ids,
          (
            SELECT GROUP_CONCAT(DISTINCT u.name ORDER BY ca.assigned_at DESC SEPARATOR '|||')
            FROM conversation_assignments ca
            JOIN users u ON ca.assigned_user_id = u.id
            WHERE ca.phone_number = m.phone_number AND ca.line_id = m.line_id
          ) as assigned_user_names,
          (
            SELECT GROUP_CONCAT(DISTINCT u.email ORDER BY ca.assigned_at DESC SEPARATOR '|||')
            FROM conversation_assignments ca
            JOIN users u ON ca.assigned_user_id = u.id
            WHERE ca.phone_number = m.phone_number AND ca.line_id = m.line_id
          ) as assigned_user_emails,
          (
            SELECT ca.assigned_at
            FROM conversation_assignments ca
            WHERE ca.phone_number = m.phone_number AND ca.line_id = m.line_id
            ORDER BY ca.assigned_at DESC
            LIMIT 1
          ) as last_assigned_at
        FROM messages m
        WHERE ${whereClause}
        GROUP BY m.phone_number, m.line_id
        ORDER BY ${sortBy} ${sortOrder}
        LIMIT :limit OFFSET :offset
      `;

      // Count query for total results
      const countQuery = `
        SELECT COUNT(*) as total
        FROM (
          SELECT m.phone_number, m.line_id, m.campaign_id
          FROM messages m
          WHERE ${whereClause}
          GROUP BY m.phone_number, m.line_id, m.campaign_id, m.campaign_name

        ) as conversations
      `;

      // Add agent filter to replacements if needed
      if (agentId) {
        replacements.agentId = parseInt(agentId);
      }

      replacements.limit = validatedLimit;
      replacements.offset = validatedOffset;

      // Execute queries
      const [conversations, countResult] = await Promise.all([
        sequelize.query(conversationsQuery, {
          replacements,
          type: sequelize.QueryTypes.SELECT,
        }),
        sequelize.query(countQuery, {
          replacements,
          type: sequelize.QueryTypes.SELECT,
        }),
      ]);

      const total = parseInt(countResult[0]?.total || 0);

      // Format conversations
      const formattedConversations = conversations.map(conv => {
        // Parse assigned users from concatenated strings
        let assignedUsers = [];
        if (conv.assigned_user_ids && conv.assigned_user_names && conv.assigned_user_emails) {
          const ids = conv.assigned_user_ids.split(',');
          const names = conv.assigned_user_names.split('|||');
          const emails = conv.assigned_user_emails.split('|||');

          assignedUsers = ids.map((id, index) => ({
            id: parseInt(id),
            name: names[index] || '',
            email: emails[index] || '',
          }));
        }

        return {
          conversationId: `${conv.phone_number}_${conv.line_id}_${conv.campaign_id || 'no-campaign'}`,
          phoneNumber: conv.phone_number,
          lineId: conv.line_id,
          firstMessageAt: conv.first_message_at,
          lastMessageAt: conv.last_message_at,
          lastMessage: {
            content: conv.last_message_content,
            direction: conv.last_message_direction,
            type: conv.last_message_type,
            status: conv.last_message_status,
          },
          statistics: {
            totalMessages: parseInt(conv.total_messages) || 0,
            incomingMessages: parseInt(conv.incoming_messages) || 0,
            outgoingMessages: parseInt(conv.outgoing_messages) || 0,
            unreadMessages: parseInt(conv.unread_messages) || 0,
          },
          campaign: conv.campaign_id ? {
            id: conv.campaign_id,
            name: conv.campaign_name,
          } : null,
          lead: conv.lead_id ? {
            id: conv.lead_id,
            name: conv.lead_name,
            email: conv.lead_email,
            status: conv.lead_status,
          } : null,
          line: {
            id: conv.line_id_ref,
            name: conv.line_name,
            phoneNumber: conv.line_phone_number,
          },
          assignedUsers: assignedUsers.length > 0 ? assignedUsers : null,
          // Keep backward compatibility with single assignedUser
          assignedUser: assignedUsers.length > 0 ? assignedUsers[0] : null,
        };
      });

      return {
        conversations: formattedConversations,
        total,
        limit: validatedLimit,
        offset: validatedOffset,
        totalPages: Math.ceil(total / validatedLimit),
      };
    } catch (error) {
      throw new Error(`Error fetching conversation history: ${error.message}`);
    }
  }

  /**
   * Get conversation detail by phone number and line ID
   * @param {string} phoneNumber - Customer phone number
   * @param {number} lineId - Phone line ID
   * @param {number} userId - User ID (for access control)
   * @param {string} userRole - User role (admin/agent)
   * @returns {Promise<Object>} Conversation detail
   */
  async getConversationDetail(phoneNumber, lineId, userId, userRole) {
    try {
      // Check access for agents
      if (userRole === 'agent') {
        const { default: PhoneLineAssignmentService } = await import('./PhoneLineAssignmentService.js');
        const assignments = await PhoneLineAssignmentService.getUserAssignedLines(userId);
        const assignedLineIds = assignments.map(a => a.line_id);

        if (!assignedLineIds.includes(parseInt(lineId))) {
          throw new Error('Access denied to this conversation');
        }
      }

      // Get all messages in conversation
      const messages = await Message.findAll({
        where: {
          phone_number: phoneNumber,
          line_id: lineId,
        },
        include: [
          {
            model: User,
            as: 'sender',
            attributes: ['id', 'name', 'email'],
          },
        ],
        order: [['created_at', 'ASC']],
      });

      // Get lead info
      const lead = await Lead.findOne({
        where: { phone_number: phoneNumber },
        attributes: ['id', 'name', 'email', 'status', 'phone_number'],
      });

      // Get line info
      const line = await PhoneLine.findByPk(lineId, {
        attributes: ['id', 'name', 'phone_number', 'display_phone_number'],
      });

      // Get assignment
      const assignment = await ConversationAssignment.findOne({
        where: {
          phone_number: phoneNumber,
          line_id: lineId,
        },
        include: [
          {
            model: User,
            as: 'assignedUser',
            attributes: ['id', 'name', 'email'],
          },
        ],
      });

      return {
        conversationId: `${phoneNumber}_${lineId}`,
        phoneNumber,
        lineId,
        messages: messages.map(m => m.toJSON()),
        lead: lead ? lead.toJSON() : null,
        line: line ? line.toJSON() : null,
        assignment: assignment ? {
          assignedUser: assignment.assignedUser ? assignment.assignedUser.toJSON() : null,
          assignedAt: assignment.assigned_at,
        } : null,
      };
    } catch (error) {
      throw new Error(`Error fetching conversation detail: ${error.message}`);
    }
  }

  /**
   * Get unique campaigns from messages
   * @returns {Promise<Array>} List of campaigns
   */
  async getCampaigns() {
    try {
      const campaigns = await Message.findAll({
        attributes: [
          [sequelize.fn('DISTINCT', sequelize.col('campaign_id')), 'campaign_id'],
          'campaign_name',
        ],
        where: {
          campaign_id: {
            [Op.ne]: null,
          },
        },
        group: ['campaign_id', 'campaign_name'],
        order: [['campaign_name', 'ASC']],
      });

      return campaigns.map(c => ({
        id: c.campaign_id,
        name: c.campaign_name,
      }));
    } catch (error) {
      throw new Error(`Error fetching campaigns: ${error.message}`);
    }
  }

  /**
   * Translate campaign name to Spanish
   * @param {string} campaignName - Campaign name to translate
   * @returns {string} Translated campaign name
   */
  translateCampaignName(campaignName) {
    if (!campaignName) return campaignName;

    // Common translations (handle both upper and lower case variations)
    const translations = {
      'schedule campaign': 'Campaña programada',
      'scheduled campaign': 'Campaña programada',
      'scheduled_campaign': 'Campaña programada',
      'schedule_campaign': 'Campaña programada',
      'schedule': 'Programada',
    };

    // Check for exact matches (case insensitive)
    const lowerName = campaignName.toLowerCase();
    for (const [key, value] of Object.entries(translations)) {
      if (lowerName === key) {
        return value;
      }
    }

    // Check for partial matches and replace
    let translatedName = campaignName;
    for (const [key, value] of Object.entries(translations)) {
      const regex = new RegExp(key, 'gi');
      if (regex.test(translatedName)) {
        translatedName = translatedName.replace(regex, value);
      }
    }

    return translatedName;
  }

  /**
   * Translate message status to Spanish
   * @param {string} status - Message status
   * @returns {string} Translated status
   */
  translateMessageStatus(status) {
    const statusMap = {
      sent: 'Enviado',
      delivered: 'Entregado',
      read: 'Leído',
      failed: 'Fallido',
      received: 'Recibido',
      pending: 'Pendiente',
    };
    return statusMap[status] || status;
  }

  /**
   * Export conversation history to Excel
   * @param {Object} filters - Same filters as getConversationHistory
   * @returns {Promise<Buffer>} Excel file buffer
   */
  async exportConversationHistoryToExcel(filters = {}) {
    try {
      // Get all conversations with filters (no pagination)
      const allFilters = { ...filters, limit: 10000, offset: 0, isExport: true };
      const { conversations } = await this.getConversationHistory(allFilters);

      // Create workbook
      const workbook = new ExcelJS.Workbook();
      const worksheet = workbook.addWorksheet('Historial de Conversaciones');

      // Define columns
      worksheet.columns = [
        { header: 'Número de Teléfono', key: 'phoneNumber', width: 20 },
        { header: 'Nombre del Contacto', key: 'leadName', width: 25 },
        { header: 'Correo Electrónico', key: 'leadEmail', width: 30 },
        { header: 'Estado del Contacto', key: 'leadStatus', width: 18 },
        { header: 'Línea Telefónica', key: 'lineName', width: 25 },
        { header: 'Campaña', key: 'campaignName', width: 30 },
        { header: 'Agentes Asignados', key: 'assignedAgents', width: 35 },
        { header: 'Primer Mensaje', key: 'firstMessageAt', width: 22 },
        { header: 'Último Mensaje', key: 'lastMessageAt', width: 22 },
        { header: 'Contenido del Último Mensaje', key: 'lastMessageContent', width: 50 },
        { header: 'Tipo de Mensaje', key: 'lastMessageType', width: 18 },
        { header: 'Estado del Mensaje', key: 'lastMessageStatus', width: 18 },
        { header: 'Dirección del Mensaje', key: 'lastMessageDirection', width: 20 },
        { header: 'Total de Mensajes', key: 'totalMessages', width: 18 },
        { header: 'Mensajes Entrantes', key: 'incomingMessages', width: 20 },
        { header: 'Mensajes Salientes', key: 'outgoingMessages', width: 20 },
        { header: 'Mensajes Sin Leer', key: 'unreadMessages', width: 20 },
      ];

      // Style header row
      worksheet.getRow(1).font = { bold: true, color: { argb: 'FFFFFFFF' } };
      worksheet.getRow(1).fill = {
        type: 'pattern',
        pattern: 'solid',
        fgColor: { argb: 'FF0d6efd' },
      };
      worksheet.getRow(1).alignment = { vertical: 'middle', horizontal: 'center' };

      // Add data rows
      conversations.forEach((conv) => {
        // Get all assigned agent names
        const assignedAgents = conv.assignedUsers && conv.assignedUsers.length > 0
          ? conv.assignedUsers.map(user => user.name).join(', ')
          : 'No asignado';

        // Format dates
        const formatDate = (date) => {
          if (!date) return 'N/A';
          return new Date(date).toLocaleString('es-ES', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
          });
        };

        worksheet.addRow({
          phoneNumber: conv.phoneNumber || 'N/A',
          leadName: conv.lead?.name || 'N/A',
          leadEmail: conv.lead?.email || 'N/A',
          leadStatus: conv.lead?.status || 'N/A',
          lineName: conv.line?.name || 'N/A',
          campaignName: conv.campaign?.name ? this.translateCampaignName(conv.campaign.name) : 'Sin campaña',
          assignedAgents,
          firstMessageAt: formatDate(conv.firstMessageAt),
          lastMessageAt: formatDate(conv.lastMessageAt),
          lastMessageContent: conv.lastMessage?.content || 'N/A',
          lastMessageType: conv.lastMessage?.type || 'N/A',
          lastMessageStatus: conv.lastMessage?.status ? this.translateMessageStatus(conv.lastMessage.status) : 'N/A',
          lastMessageDirection: conv.lastMessage?.direction === 'incoming' ? 'Entrante' : 'Saliente',
          totalMessages: conv.statistics?.totalMessages || 0,
          incomingMessages: conv.statistics?.incomingMessages || 0,
          outgoingMessages: conv.statistics?.outgoingMessages || 0,
          unreadMessages: conv.statistics?.unreadMessages || 0,
        });
      });

      // Add alternating row colors
      worksheet.eachRow((row, rowNumber) => {
        if (rowNumber > 1 && rowNumber % 2 === 0) {
          row.fill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: 'FFF8F9FA' },
          };
        }
      });

      // Generate buffer
      const buffer = await workbook.xlsx.writeBuffer();
      return buffer;
    } catch (error) {
      throw new Error(`Error exporting conversation history: ${error.message}`);
    }
  }
}

export default new ConversationHistoryService();

